CREATE TABLE "NOTADEZ"."DOCENTE" ( "ID_DOCENTE" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE, "NOME_DOCENTE" VARCHAR2(100 BYTE) NOT NULL ENABLE, "EMAIL_DOCENTE" VARCHAR2(100 BYTE), "SENHA" VARCHAR2(100 BYTE), "CREATED_AT" DATE DEFAULT CURRENT_DATE, "TELEFONE" VARCHAR2(100 BYTE) ) SEGMENT CREATION IMMEDIATE PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 NOCOMPRESS LOGGING STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT) TABLESPACE "DATA" ; ALTER TABLE "NOTADEZ"."DOCENTE" ADD PRIMARY KEY ("ID_DOCENTE") USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT) TABLESPACE "DATA" ENABLE; ALTER TABLE "NOTADEZ"."DOCENTE" ADD UNIQUE ("EMAIL_DOCENTE") USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT) TABLESPACE "DATA" ENABLE; ALTER TABLE "NOTADEZ"."DOCENTE" ADD UNIQUE ("SENHA") USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT) TABLESPACE "DATA" ENABLE;

CREATE TABLE turmas ( id_turma NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nome_turma VARCHAR2(100) NOT NULL, horario_aula TIMESTAMP NOT NULL, -- Oracle TIMESTAMP armazena data e hora local_aula VARCHAR2(100) NOT NULL, dia_aula VARCHAR2(20) NOT NULL );

CREATE TABLE disciplinas ( id_disciplina NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, sigla_disciplina VARCHAR2(20) NOT NULL, nome_disciplina VARCHAR2(100) NOT NULL, periodo DATE NOT NULL -- TIME nao e um tipo nativo, DATE armazena data e hora );

CREATE TABLE instituicoes ( id_instituicao NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nome_instituicao VARCHAR2(100) NOT NULL );

CREATE TABLE cursos ( id_curso NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nome_curso VARCHAR2(100) NOT NULL, id_instituicao NUMBER NOT NULL, FOREIGN KEY (id_instituicao) REFERENCES instituicoes(id_instituicao) );

CREATE TABLE notas ( id_nota NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, id_turma NUMBER NOT NULL, valor_nota NUMBER NOT NULL, -- FLOAT e sinonimo de NUMBER data_lancamento DATE NOT NULL, FOREIGN KEY (id_turma) REFERENCES turmas(id_turma) );

CREATE TABLE alunos ( ra_aluno NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nome_aluno VARCHAR2(100) NOT NULL );

CREATE TABLE componentes_nota ( id_componente NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, id_disciplina NUMBER NOT NULL, nome_componente VARCHAR2(100) NOT NULL, descricao VARCHAR2(255) NOT NULL, sigla_componente VARCHAR2(20) NOT NULL, FOREIGN KEY (id_disciplina) REFERENCES disciplinas(id_disciplina) );

CREATE TABLE formula_nota_final ( id_formula NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, id_disciplina NUMBER NOT NULL, tipo_formula VARCHAR2(50) NOT NULL, peso_p1 NUMBER NOT NULL, peso_p2 NUMBER NOT NULL, peso_p3 NUMBER NOT NULL, formula_text VARCHAR2(255) NOT NULL, FOREIGN KEY (id_disciplina) REFERENCES disciplinas(id_disciplina) );

CREATE TABLE auditoria_notas ( id_auditoria NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, ra_aluno NUMBER NOT NULL, id_componente NUMBER NOT NULL, id_docente NUMBER NOT NULL, valor_antigo NUMBER NOT NULL, valor_novo NUMBER NOT NULL, data_hora TIMESTAMP NOT NULL, -- Oracle TIMESTAMP para data e hora FOREIGN KEY (ra_aluno) REFERENCES alunos(ra_aluno), FOREIGN KEY (id_componente) REFERENCES componentes_nota(id_componente), FOREIGN KEY (id_docente) REFERENCES docentes(id_docente) );

-- Tabelas Associativas (muitos-para-muitos)

CREATE TABLE cadastro ( id_docente NUMBER NOT NULL, id_instituicao NUMBER NOT NULL, PRIMARY KEY (id_docente, id_instituicao), FOREIGN KEY (id_docente) REFERENCES docentes(id_docente), FOREIGN KEY (id_instituicao) REFERENCES instituicoes(id_instituicao) );

CREATE TABLE matriculam ( id_turma NUMBER NOT NULL, ra_aluno NUMBER NOT NULL, PRIMARY KEY (id_turma, ra_aluno), FOREIGN KEY (id_turma) REFERENCES turmas(id_turma), FOREIGN KEY (ra_aluno) REFERENCES alunos(ra_aluno) );

CREATE TABLE turma_disciplina ( id_disciplina NUMBER NOT NULL, id_turma NUMBER NOT NULL, PRIMARY KEY (id_disciplina, id_turma), FOREIGN KEY (id_disciplina) REFERENCES disciplinas(id_disciplina), FOREIGN KEY (id_turma) REFERENCES turmas(id_turma) );

/Trigger para auditoria automatica - UPDATE/ create or replace trigger notadez.trigger_auditoria_notas_update before update on notadez.notas for each row begin insert into notadez.auditoria_notas ( ra_aluno, id_componente, valor_antigo, valor_novo, id_docente ) values ( :old.ra_aluno, :old.id_componente, :old.valor_nota, :new.valor_nota, 1 ); end; /

/Trigger para auditoria automatica - INSERT/ create or replace trigger notadez.trigger_auditoria_notas_insert after insert on notadez.notas for each row begin insert into notadez.auditoria_notas ( ra_aluno, id_componente, valor_antigo, valor_novo, id_docente ) values ( :new.ra_aluno, :new.id_componente, null, :new.valor_nota, 1 ); end; /
